new="function defaultState(){return {v:6,name:'Explorer',xp:0,stars:{},done:{},badges:{},streak:1,lastDay:(new Date()).toDateString(),lessons:0,voice:true,sound:true,ellieMemory:[],dailyDone:false,created:(new Date()).getTime(),ellieBrain:{turns:0,lastSeen:0,lastTopic:'',interests:[],goals:[],favorites:[],wins:[],struggles:[]}}}"
