old="function mergeState(base,src){var k;if(!src||typeof src!=='object')return base;for(k in src)if(own(src,k))base[k]=src[k];base.stars=base.stars||{};base.done=base.done||{};base.badges=base.badges||{};base.ellieMemory=base.ellieMemory||[];return base}"
new="function mergeState(base,src){var k;if(!src||typeof src!=='object')return base;for(k in src)if(own(src,k))base[k]=src[k];base.stars=base.stars||{};base.done=base.done||{};base.badges=base.badges||{};base.ellieMemory=base.ellieMemory||[];base.ellieBrain=base.ellieBrain||defaultState().ellieBrain;base.ellieBrain.interests=base.ellieBrain.interests||[];base.ellieBrain.goals=base.ellieBrain.goals||[];base.ellieBrain.favorites=base.ellieBrain.favorites||[];base.ellieBrain.wins=base.ellieBrain.wins||[];base.ellieBrain.struggles=base.ellieBrain.struggles||[];return base}"
