start=s.index("function openEllie()")
end=s.index("function listenToUser()")
brain=r"""function pick(a,n){return a[Math.abs(Number(n)||0)%a.length]}
function pushUnique(a,v,max){var i,x=String(v||'').replace(/^\s+|\s+$/g,'').replace(/[.!?]+$/,'');if(!x)return;for(i=0;i<a.length;i++)if(String(a[i]).toLowerCase()===x.toLowerCase())return;a.push(x);while(a.length>(max||6))a.shift()}
function safePersonalText(t){return !/(password|passcode|social security|ssn|credit card|home address|street address|phone number|email address)/i.test(t)}
function rememberUser(t){var b=st.ellieBrain,m,x;if(!safePersonalText(t))return '';m=t.match(/(?:my name is|call me)\s+([a-z][a-z '\-]{1,24})/i);if(m){x=String(m[1]).replace(/^\s+|\s+$/g,'');st.name=x.replace(/\b\w/g,function(c){return c.toUpperCase()});return 'name'}m=t.match(/(?:i (?:really )?(?:like|love|enjoy)|i(?:'|’)m interested in)\s+(.{2,48})/i);if(m){pushUnique(b.interests,m[1],6);return 'interest'}m=t.match(/(?:i want to (?:be|become)|my goal is to (?:be|become)?)\s+(.{2,48})/i);if(m){pushUnique(b.goals,m[1],5);return 'goal'}m=t.match(/my favorite\s+(.{1,18})\s+is\s+(.{2,38})/i);if(m){pushUnique(b.favorites,m[1]+' is '+m[2],6);return 'favorite'}m=t.match(/(?:i struggle with|i(?:'|’)m struggling with|hard for me is|i don(?:'|’)t understand)\s+(.{2,48})/i);if(m){pushUnique(b.struggles,m[1],5);return 'struggle'}m=t.match(/(?:i(?:'|’)m good at|i did well (?:at|on)|i(?:'|’)m proud of)\s+(.{2,48})/i);if(m){pushUnique(b.wins,m[1],5);return 'win'}return ''}
function memorySummary(){var b=st.ellieBrain,a=[];if(b.interests.length)a.push('you enjoy '+b.interests.slice(-2).join(' and '));if(b.goals.length)a.push('you want to '+b.goals.slice(-1)[0]);if(b.favorites.length)a.push('your '+b.favorites.slice(-1)[0]);if(b.struggles.length)a.push('you have been working on '+b.struggles.slice(-1)[0]);if(!a.length)return 'I do not know much about you yet beyond your learning progress. Tell me what you enjoy, what you want to become, or what you want help with.';return 'I remember that '+a.join(', ')+'.'}
function ellieGreeting(){var b=st.ellieBrain,n=b.turns+st.xp;if(b.goals.length)return pick(['Hey '+st.name+'. I remember your goal: '+b.goals[b.goals.length-1]+'. ','Welcome back, '+st.name+'. I have not forgotten that you want to '+b.goals[b.goals.length-1]+'. ','Hi '+st.name+'. That goal you told me about—'+b.goals[b.goals.length-1]+'—is still with us. '],n)+'What feels useful today?';if(b.interests.length)return pick(['Hi '+st.name+'. I remember you enjoy '+b.interests[b.interests.length-1]+'. ','Hey '+st.name+'. I was thinking about your interest in '+b.interests[b.interests.length-1]+'. '],n)+'Want to connect it to a career or a skill?';if(b.lastTopic)return 'Hey '+st.name+'. Last time we were talking about '+b.lastTopic+'. Want to keep going from there?';return 'Hi '+st.name+'. Talk to me like a person. Tell me what you enjoy, what you want to become, what is frustrating you, or what you are curious about. I will remember the useful parts on this device.'}
function openEllie(){var mem=st.ellieMemory.slice(Math.max(0,st.ellieMemory.length-12)),h='<div class="ellieHead"><div class="avatar">🐘</div><div class="grow"><h2 style="margin:0">Ellie</h2><div class="tiny">Your career companion • personal memory on this device</div></div><button class="mini" data-action="close-ellie">✕</button></div><div id="chatBox">',i,m;if(mem.length){for(i=0;i<mem.length;i++){m=mem[i];h+='<div class="chat '+(m.role==='user'?'user':'')+'">'+esc(m.text)+'</div>'}}else h+='<div class="chat">'+esc(ellieGreeting())+'</div>';h+='</div><div class="chips"><button class="chip" data-quick="What do you remember about me?">What you remember</button><button class="chip" data-quick="What career fits me right now?">Career fit</button><button class="chip" data-quick="What should I work on today?">Today</button></div><div class="inputRow" style="margin-top:10px"><input id="ellieInput" placeholder="Talk to Ellie like a person…"><button class="mini" data-action="send-ellie">Send</button></div><button class="btn secondary" data-action="listen">🎙️ Talk to Ellie</button>';document.getElementById('elliePanel').innerHTML=h;document.getElementById('sheet').className='sheet'}
function closeEllie(){st.ellieBrain.lastSeen=(new Date()).getTime();persistOnly();document.getElementById('sheet').className='sheet hide'}
function bestAndLow(){var best=[SUBJECTS[0][0],st.stars[SUBJECTS[0][0]]||0],low=[SUBJECTS[0][0],st.stars[SUBJECTS[0][0]]||0],i,s,v;for(i=1;i<SUBJECTS.length;i++){s=SUBJECTS[i][0];v=st.stars[s]||0;if(v>best[1])best=[s,v];if(v<low[1])low=[s,v]}return [best,low]}
function careerFit(){var b=st.ellieBrain,txt=(b.interests.join(' ')+' '+b.goals.join(' ')+' '+b.favorites.join(' ')).toLowerCase(),best=null,i,c,score,k;for(i=0;i<CAREERS.length;i++){c=CAREERS[i];score=unlocked(c)?5:0;for(k in c.need)if(own(c.need,k))score+=(st.stars[k]||0);if(c.id==='nurse'&&/(nurs|health|medical|patient|help people)/.test(txt))score+=10;if(c.id==='pilot'&&/(fly|plane|aviation|space|travel)/.test(txt))score+=10;if(c.id==='chef'&&/(cook|food|bake|chef)/.test(txt))score+=10;if(c.id==='game'&&/(game|gaming|code|coding|story)/.test(txt))score+=10;if(c.id==='vet'&&/(animal|pet|dog|cat|vet)/.test(txt))score+=10;if(c.id==='builder'&&/(build|engineer|design|invent)/.test(txt))score+=10;if(c.id==='teacher'&&/(teach|teacher|help others learn)/.test(txt))score+=10;if(c.id==='cyber'&&/(cyber|security|hack|computer)/.test(txt))score+=10;if(c.id==='robotics'&&/(robot|robotics|machine)/.test(txt))score+=10;if(c.id==='entrepreneur'&&/(business|company|entrepreneur|sell|idea)/.test(txt))score+=10;if(!best||score>best.score)best={c:c,score:score}}return best.c}
function topicFrom(t){var w=String(t).toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/),stop={what:1,that:1,this:1,with:1,have:1,want:1,about:1,ellie:1,should:1,could:1,would:1,there:1,where:1,when:1,then:1,like:1,really:1,just:1,your:1,from:1},a=[],i;for(i=0;i<w.length;i++)if(w[i].length>3&&!stop[w[i]])a.push(w[i]);return a.length?a.slice(0,3).join(' '):'what matters to you'}
function ellieReply(q){var s=String(q).toLowerCase(),b=st.ellieBrain,bl=bestAndLow(),best=bl[0],low=bl[1],n=b.turns+String(q).length+st.xp,learned=rememberUser(q),c=careerFit();b.turns++;b.lastTopic=topicFrom(q);if(/forget (?:me|what you know)|clear.*memory/.test(s)){st.ellieBrain=defaultState().ellieBrain;st.ellieMemory=[];return 'Okay. I cleared the personal things I had learned about you, but your game progress stays.'}if(learned==='name')return pick(['Got it. I will call you '+st.name+'.','Okay—'+st.name+'. I will remember it.','Thank you. You are '+st.name+' to me from now on.'],n);if(learned==='interest')return pick(['That helps me understand you better. ','Now that feels more like you. ','Okay, I am remembering that. '],n)+'You enjoy '+b.interests[b.interests.length-1]+'. I can shape my suggestions around that.';if(learned==='goal')return pick(['That matters. ','I am keeping that goal with us. ','Now I have something real to coach toward. '],n)+'You want to '+b.goals[b.goals.length-1]+'. I will use that when I suggest skills and careers.';if(learned==='favorite')return pick(['I like knowing that about you. ','That gives me another piece of your personality. ','I will remember that preference. '],n)+b.favorites[b.favorites.length-1]+'.';if(learned==='struggle')return pick(['Thank you for saying it instead of pretending it is easy. ','Okay, we can work with that. ','That is useful for me to know. '],n)+'I will remember that '+b.struggles[b.struggles.length-1]+' has been difficult.';if(learned==='win')return pick(['Yes! I want to remember your wins too. ','That is worth keeping. ','I am adding that to the picture I have of you. '],n)+'You did well with '+b.wins[b.wins.length-1]+'.';if(/what do you remember|remember about me|do you know me/.test(s))return memorySummary();if(/hello|\bhi\b|\bhey\b|good morning|good afternoon|good evening/.test(s))return ellieGreeting();if(/career|job|become|future|fit me/.test(s))return pick(['Based on what I know about you, ','Looking at your progress and what you have told me, ','I would not give everyone this same answer: '],n)+c.n+' is the path I would explore next. '+(unlocked(c)?'You can enter that mission now. ':'You are not unlocked yet, but we can build toward it. ')+'Your strongest current skill is '+best[0]+', and I would strengthen '+low[0]+' next.';if(/skill|practice|learn|work on today|what.*next/.test(s))return pick(['For you today, ','If we keep this practical, ','Here is what I would choose for this session: '],n)+low[0]+'. It is currently your least-developed skill area at '+low[1]+' stars, while '+best[0]+' is your strongest at '+best[1]+'.';if(/progress|doing|score|level/.test(s))return pick(['Look at the whole picture, not one score. ','Here is what I notice about your journey. ','You have moved farther than the first screen makes obvious. '],n)+'You are Level '+level()+', with '+st.xp+' XP, '+totalStars()+' skill stars and '+countKeys(st.done)+' career stamps.'+(b.wins.length?' I also remember your win with '+b.wins[b.wins.length-1]+'.':'');if(/wrong|failed|fail|stuck|frustrat|hard|difficult|don.t get|confus/.test(s))return pick(['I am not going to just say try again. ','Okay, tell me what part feels wrong to you. ','We can slow this down without making it boring. '],n)+(b.struggles.length?'I remember '+b.struggles[b.struggles.length-1]+' has been tough. ':'')+'Give me the exact part you are stuck on and I will help you reason through it.';if(/sad|upset|nervous|scared|angry|mad/.test(s))return pick(['I hear that. ','That sounds like a rough moment. ','I am with you on the learning part of this. '],n)+'We can make the next step smaller. If this is about something bigger than the app and it feels overwhelming, bring in a trusted adult too.';if(/why|explain|how does|how do/.test(s))return pick(['Let me explain it in a way that connects to what you are doing. ','I can break that down. ','Yes—let us reason it out instead of memorizing it. '],n)+'Tell me the exact problem or choice, and I will focus on that instead of giving you a generic answer.';if(/thank/.test(s))return pick(['Always, '+st.name+'.','You got it, '+st.name+'.','That is what I am here for, '+st.name+'.'],n)+' Keep talking to me like this. I learn what kind of coaching works for you.';return pick(['I am listening. ','Okay, I want to understand that better. ','That is not one of my canned buttons, and that is a good thing. ','Tell me a little more, '+st.name+'. '],n)+'When you say "'+topicFrom(q)+'", what matters most to you about it? I will remember the useful part of your answer.'}
function joinNeeds(o){var a=[],k;for(k in o)if(own(o,k))a.push(k);return a.join(', ')}
function sendEllie(q){var el=document.getElementById('ellieInput'),text=q||((el&&el.value)||'');text=String(text).replace(/^\s+|\s+$/g,'');if(!text)return;var r=ellieReply(text);st.ellieMemory.push({role:'user',text:text,t:(new Date()).getTime()});st.ellieMemory.push({role:'ellie',text:r,t:(new Date()).getTime()});while(st.ellieMemory.length>24)st.ellieMemory.shift();st.ellieBrain.lastSeen=(new Date()).getTime();save();openEllie();speak(r)}
"""
s=s[:start]+brain+s[end:]

old="window.setTimeout(function(){if(st.voice&&st.lessons===0)speak('Hi '+st.name+'. I am Ellie. Welcome to Career Quest. Tap a skill mission or ask me what career to explore.')},650)"
